<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Event;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class EventController extends Controller{public function index(){return Event::where('published',true)->where(fn($q)=>$q->whereNull('ends_at')->where('starts_at','>=',now())->orWhere('ends_at','>=',now()))->orderByDesc('featured')->orderBy('starts_at')->paginate(12);}public function featured(){return Event::where(['published'=>true,'featured'=>true])->where(fn($q)=>$q->whereNull('ends_at')->where('starts_at','>=',now())->orWhere('ends_at','>=',now()))->orderBy('starts_at')->first();}public function adminIndex(){return Event::withCount(['attendees','photos'])->orderByDesc('starts_at')->paginate(30);}public function store(Request $request){$data=$this->validated($request);$data['created_by']=$request->user()->id;if($request->hasFile('image'))$data['image_url']=$this->storeImage($request);if($data['featured']??false)Event::query()->update(['featured'=>false]);return response()->json(Event::create($data),201);}public function update(Request $request,Event $event){$data=$this->validated($request,true);if($request->hasFile('image')){$this->deleteLocalImage($event->image_url);$data['image_url']=$this->storeImage($request);}if($data['featured']??false)Event::where('id','!=',$event->id)->update(['featured'=>false]);$event->update($data);return $event->fresh();}public function destroy(Event $event){$this->deleteLocalImage($event->image_url);$event->delete();return response()->json(['message'=>'Event deleted.']);}private function validated(Request $request,bool $partial=false):array{$r=$partial?'sometimes':'required';return $request->validate(['title'=>"$r|string|max:180",'description'=>"$r|string|max:5000",'starts_at'=>"$r|date",'ends_at'=>'nullable|date|after_or_equal:starts_at','location'=>"$r|string|max:180",'category'=>'sometimes|string|max:100','registration_url'=>'nullable|url|max:500','published'=>'sometimes|boolean','featured'=>'sometimes|boolean','image'=>'sometimes|image|mimes:jpeg,jpg,png,webp|max:10240']);}private function storeImage(Request $request):string{return Storage::disk('public')->url($request->file('image')->store('events/covers','public'));}private function deleteLocalImage(?string $url):void{if($url&&str_contains($url,'/storage/'))Storage::disk('public')->delete(str($url)->after('/storage/')->toString());}}
